import { FeatureCollection, Polygon, MultiPolygon, Feature } from 'geojson';

/** A state / union-territory boundary. */
interface StateProps {
    /** Canonical English name, e.g. "Telangana". */
    name: string;
    /** ISO 3166-2:IN style code where known, e.g. "IN-TG". */
    code?: string;
}
/** A district boundary. */
interface DistrictProps {
    /** Canonical English district name, e.g. "Khammam". */
    name: string;
    /** Parent state / UT name, e.g. "Telangana". */
    state: string;
}
type StateGeometry = Polygon | MultiPolygon;
type StateFeature = Feature<StateGeometry, StateProps>;
type DistrictFeature = Feature<StateGeometry, DistrictProps>;
type StateCollection = FeatureCollection<StateGeometry, StateProps>;
type DistrictCollection = FeatureCollection<StateGeometry, DistrictProps>;
/** Metadata describing how the bundled dataset was produced. */
interface DatasetMeta {
    /** Dataset semver, independent of the package version. */
    version: string;
    /** ISO date the data was generated. */
    generated: string;
    /** Upstream source, always OpenStreetMap for now. */
    source: string;
    /** Available resolution tiers, e.g. ["low","high"]. */
    resolutions: string[];
    /** The tier bundled eagerly / used when none is specified. */
    defaultResolution: string;
    /** True once GoI disputed-border corrections have been applied. */
    goiBordersPatched: boolean;
    /** Human note about coverage / caveats. */
    note: string;
    stateCount: number;
    districtCount: number;
}

export type { DatasetMeta as D, StateCollection as S, DistrictCollection as a, DistrictFeature as b, DistrictProps as c, StateFeature as d, StateGeometry as e, StateProps as f };
